assert.equal(classifyBuilderCustody({...beforeCall,original:Promise.resolve()}).known,false);
assert.equal(classifyBuilderCustody({state:'threw',callEntered:true,joined:false,cause:undefined}).known,false);
function custody(original,internalObserver){
 const observer=original.then(()=>undefined,()=>undefined);
 return {state:'pending',callEntered:true,joined:false,original,returned:original,observer,internalObserver,internalObserverAssociated:true};
}
