const known=custody(Promise.reject(originalCause),Promise.resolve());
await joinBuilderCustody(known);
assert.equal(known.originalOutcome.reason,originalCause);
assert.equal(known.driverObserverOutcome.status,'fulfilled');
assert.equal(known.internalObserverOutcome.status,'fulfilled');
assert.equal(known.joined,true);assert.equal(classifyBuilderCustody(known).known,true);
assert.equal(canRetireDriver(known,[settledRecord],[],false),true);
const unknown=custody(Promise.resolve('inert-return'),Promise.reject(undefined));
await joinBuilderCustody(unknown);
assert.equal(unknown.joined,true);assert.equal(unknown.internalObserverOutcome.status,'rejected');
assert.equal(Object.hasOwn(unknown.internalObserverOutcome,'reason'),true);
assert.deepEqual(describeOutcome(unknown.internalObserverOutcome),{status:'rejected',reason:{type:'undefined',text:'undefined'}});
assert.equal(classifyBuilderCustody(unknown).known,false,'actual rejected internal observer must remain UNKNOWN');
assert.equal(canRetireDriver(unknown,[settledRecord],[],false),false);
const unknownDriver=custody(Promise.resolve(),Promise.resolve());unknownDriver.observer=Promise.reject('inert observer error');
await joinBuilderCustody(unknownDriver);assert.equal(classifyBuilderCustody(unknownDriver).known,false);
const absent=custody(Promise.resolve(),undefined);await joinBuilderCustody(absent);assert.equal(absent.joined,false);assert.equal(classifyBuilderCustody(absent).known,false);
assert.equal(canRetireDriver({...known,joined:false},[settledRecord],[],false),false);
assert.equal(canRetireDriver(known,[settledRecord],[],true),false);
assert.equal(canRetireDriver(known,[{label:'failure.write',state:'pending',joined:false}],[],false),false);
assert.equal(canRetireDriver(known,[{label:'failure.write',state:'rejected',joined:true}],[],false),false);
assert.equal(canRetireDriver(known,[{label:'failure.write',state:'fulfilled',joined:true}],[],false),true);
