 get name(){return 'ResolveMessage';}get message(){return 'inert resolver refusal';}get position(){return new GetterPosition();}
 get code(){return 'MODULE_NOT_FOUND';}get referrer(){return '/sealed/input.ts';}get specifier(){return './absent.ts';}get importKind(){return 'stmt';}
}
